using System.ComponentModel;

namespace HorusStudio.Maui.MaterialDesignControls.Sample.Benchmarks.XamlProbes;

/// <summary>
/// Binding source for the two binding probes. Hand-written rather than
/// generated by the MVVM toolkit so the notification path is identical and
/// obvious: one shared <see cref="PropertyChangedEventArgs"/> per property,
/// allocated once, so the measurement does not include allocating them.
/// </summary>
public sealed class XamlBindProbe : INotifyPropertyChanged
{
    public event PropertyChangedEventHandler? PropertyChanged;

    private static readonly PropertyChangedEventArgs NameArgs = new(nameof(Name));
    private static readonly PropertyChangedEventArgs EmailArgs = new(nameof(Email));
    private static readonly PropertyChangedEventArgs DepartmentArgs = new(nameof(Department));
    private static readonly PropertyChangedEventArgs RoleArgs = new(nameof(Role));
    private static readonly PropertyChangedEventArgs ScoreArgs = new(nameof(Score));
    private static readonly PropertyChangedEventArgs StatusArgs = new(nameof(Status));
    private static readonly PropertyChangedEventArgs LocationArgs = new(nameof(Location));
    private static readonly PropertyChangedEventArgs UpdatedArgs = new(nameof(Updated));

    public string Name { get; private set; } = "name-0";
    public string Email { get; private set; } = "email-0";
    public string Department { get; private set; } = "department-0";
    public string Role { get; private set; } = "role-0";
    public string Score { get; private set; } = "score-0";
    public string Status { get; private set; } = "status-0";
    public string Location { get; private set; } = "location-0";
    public string Updated { get; private set; } = "updated-0";

    private int _revision;

    /// <summary>
    /// Rewrites every property and raises a change notification for each one,
    /// which is what a real list row does when its item is replaced.
    /// </summary>
    public void Bump()
    {
        _revision++;
        var handler = PropertyChanged;
        Name = "name-" + _revision;
        Email = "email-" + _revision;
        Department = "department-" + _revision;
        Role = "role-" + _revision;
        Score = "score-" + _revision;
        Status = "status-" + _revision;
        Location = "location-" + _revision;
        Updated = "updated-" + _revision;
        if (handler is null) return;
        handler(this, NameArgs);
        handler(this, EmailArgs);
        handler(this, DepartmentArgs);
        handler(this, RoleArgs);
        handler(this, ScoreArgs);
        handler(this, StatusArgs);
        handler(this, LocationArgs);
        handler(this, UpdatedArgs);
    }

    /// <summary>Bindings declared per probe instance (5 blocks x 8 properties).</summary>
    public const int BindingsPerInstance = 40;
}
